def decode():
    rows=ROWS.strip().split(';'); assert len(rows)==133,len(rows)
    g=np.zeros((133,150),dtype=bool)
    for y,row in enumerate(rows):
        for part in row.split(','):
            if not part:continue
            left,width=(int(a,36) for a in part.split(':'))
            g[y,left:left+width]=True
    assert int(g.sum())==3157,int(g.sum())
    return g

